"""Render the nearly identical rollouts generated by ``generate_chaos_ensemble``.

Run:
    .venv\\Scripts\\manim -pql examples/render_chaos_ensemble.py ChaosEnsemble
"""

from __future__ import annotations

from pathlib import Path

import numpy as np
from manim import BLUE, GREEN, ORANGE, ORIGIN, PINK, PURPLE, RED, YELLOW, Dot, Line, Scene, ValueTracker, always_redraw, linear

from sim.animation import bob_positions

PROJECT_ROOT = Path(__file__).resolve().parents[1]
TRAJECTORY_PATH = PROJECT_ROOT / "artifacts" / "chaos_ensemble.npz"
COLORS = [BLUE, GREEN, YELLOW, ORANGE, RED, PINK, PURPLE]
ANIMATION_SECONDS = 60.0


class ChaosEnsemble(Scene):
    def construct(self) -> None:
        data = np.load(TRAJECTORY_PATH)
        time = data["time"]
        state = data["state"]  # shape: (ensemble_size, T, 4)
        length_1 = float(data["length_1"])
        length_2 = float(data["length_2"])
        if time.ndim != 1 or state.ndim != 3 or state.shape[1:] != (time.size, 4):
            raise ValueError("expected time=(T,) and state=(ensemble_size, T, 4)")

        clock = ValueTracker(float(time[0]))

        def positions_now(index: int) -> np.ndarray:
            current = np.array(
                [np.interp(clock.get_value(), time, state[index, :, column]) for column in range(4)]
            )
            positions_2d = bob_positions(current, length_1, length_2)[0]
            return np.column_stack((positions_2d, np.zeros(positions_2d.shape[0])))

        self.add(Dot(ORIGIN, color=BLUE))
        for index in range(state.shape[0]):
            color = COLORS[index % len(COLORS)]
            self.add(
                always_redraw(lambda index=index, color=color: Line(positions_now(index)[0], positions_now(index)[1], color=color, stroke_width=2)),
                always_redraw(lambda index=index, color=color: Dot(positions_now(index)[1], color=color, radius=0.06)),
                always_redraw(lambda index=index, color=color: Line(positions_now(index)[1], positions_now(index)[2], color=color, stroke_width=2)),
                always_redraw(lambda index=index, color=color: Dot(positions_now(index)[2], color=color, radius=0.07)),
            )
        self.play(
            clock.animate.set_value(float(time[-1])),
            run_time=ANIMATION_SECONDS,
            rate_func=linear,
        )
